mapper.select:
SELECT COUNT(1)
FROM T_ACCOUNTING_VOUCHER v
WHERE v.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_TYPE_ID = #{param.voucherTypeId}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}


    AND v.PREPARER = #{param.preparer}

SELECT COALESCE(SUM(v.TOTAL_DEBIT), 0)
FROM T_ACCOUNTING_VOUCHER v
WHERE v.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_TYPE_ID = #{param.voucherTypeId}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}


    AND v.PREPARER = #{param.preparer}

SELECT v.VOUCHER_STATUS as status, CASE v.VOUCHER_STATUS WHEN 0 THEN '草稿' WHEN 1 THEN '已生成' WHEN 2 THEN '已过账' WHEN 3 THEN '已取消' ELSE '未知' END as statusName, COUNT(1) as count, COALESCE(SUM(v.TOTAL_DEBIT), 0) as amount FROM T_ACCOUNTING_VOUCHER v WHERE v.IS_DELETED = 0
AND v.BOOK_ID = #{param.bookId}
AND v.TENANT_ID = #{param.tenantId}
AND v.VOUCHER_DATE >= #{param.startDate}
AND v.VOUCHER_DATE <= #{param.endDate}
AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}
GROUP BY v.VOUCHER_STATUS ORDER BY v.VOUCHER_STATUS

SELECT
    v.ACCOUNTING_PERIOD as period,
    v.ACCOUNTING_PERIOD as accountingPeriod,
    COUNT(1) as count,
    COALESCE(SUM(v.TOTAL_DEBIT), 0) as amount
FROM T_ACCOUNTING_VOUCHER v
WHERE v.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}

AND v.ACCOUNTING_PERIOD IS NOT NULL
GROUP BY v.ACCOUNTING_PERIOD
ORDER BY v.ACCOUNTING_PERIOD DESC

SELECT
    v.VOUCHER_TYPE_ID as typeId,
    vt.TYPE_NAME as typeName,
    COUNT(1) as count,
    COALESCE(SUM(v.TOTAL_DEBIT), 0) as amount
FROM T_ACCOUNTING_VOUCHER v
LEFT JOIN T_VOUCHER_TYPE vt ON v.VOUCHER_TYPE_ID = vt.VOUCHER_TYPE_ID
WHERE v.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}

AND v.VOUCHER_TYPE_ID IS NOT NULL
GROUP BY v.VOUCHER_TYPE_ID, vt.TYPE_NAME
ORDER BY count DESC

SELECT
    v.PREPARER as preparerId,
    s.STAFF_NAME as preparerName,
    COUNT(1) as count,
    COALESCE(SUM(v.TOTAL_DEBIT), 0) as amount
FROM T_ACCOUNTING_VOUCHER v
LEFT JOIN TBL_STAFF s ON v.PREPARER = s.STAFF_ID
WHERE v.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}

AND v.PREPARER IS NOT NULL
GROUP BY v.PREPARER, s.STAFF_NAME
ORDER BY count DESC

SELECT
    ve.CURRENCY_CODE as currencyCode,
    ve.CURRENCY_CODE as currencyName,
    COUNT(DISTINCT v.VOUCHER_ID) as count,
    COALESCE(SUM(ve.DEBIT_AMOUNT), 0) as debitAmount,
    COALESCE(SUM(ve.CREDIT_AMOUNT), 0) as creditAmount
FROM T_ACCOUNTING_VOUCHER v
INNER JOIN T_VOUCHER_ENTRY ve ON v.VOUCHER_ID = ve.VOUCHER_ID
WHERE v.IS_DELETED = 0
AND ve.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}

AND ve.CURRENCY_CODE IS NOT NULL
GROUP BY ve.CURRENCY_CODE
ORDER BY count DESC

SELECT COUNT(1)
FROM T_VOUCHER_ENTRY ve
INNER JOIN T_ACCOUNTING_VOUCHER v ON ve.VOUCHER_ID = v.VOUCHER_ID
WHERE v.IS_DELETED = 0
AND ve.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}

SELECT COALESCE(SUM(ve.DEBIT_AMOUNT), 0)
FROM T_VOUCHER_ENTRY ve
INNER JOIN T_ACCOUNTING_VOUCHER v ON ve.VOUCHER_ID = v.VOUCHER_ID
WHERE v.IS_DELETED = 0
AND ve.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}

SELECT COALESCE(SUM(ve.CREDIT_AMOUNT), 0)
FROM T_VOUCHER_ENTRY ve
INNER JOIN T_ACCOUNTING_VOUCHER v ON ve.VOUCHER_ID = v.VOUCHER_ID
WHERE v.IS_DELETED = 0
AND ve.IS_DELETED = 0

    AND v.BOOK_ID = #{param.bookId}


    AND v.TENANT_ID = #{param.tenantId}


    AND v.VOUCHER_STATUS = #{param.voucherStatus}


    AND v.VOUCHER_DATE >= #{param.startDate}


    AND v.VOUCHER_DATE <= #{param.endDate}


    AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod}

SELECT
    v.VOUCHER_DATE as date,
    COUNT(1) as count,
    COALESCE(SUM(v.TOTAL_DEBIT), 0) as amount
FROM T_ACCOUNTING_VOUCHER v
WHERE v.IS_DELETED = 0
AND v.BOOK_ID = #{bookId}
AND v.TENANT_ID = #{tenantId}
AND v.VOUCHER_DATE >= #{startDate}
AND v.VOUCHER_DATE <= #{endDate}
GROUP BY v.VOUCHER_DATE
ORDER BY v.VOUCHER_DATE

SELECT ve.ACCOUNT_CODE as accountCode, a.ACCOUNT_NAME as accountName, COUNT(1) as usageCount, COALESCE(SUM(ve.DEBIT_AMOUNT), 0) as totalDebitAmount, COALESCE(SUM(ve.CREDIT_AMOUNT), 0) as totalCreditAmount FROM T_VOUCHER_ENTRY ve INNER JOIN T_ACCOUNTING_VOUCHER v ON ve.VOUCHER_ID = v.VOUCHER_ID LEFT JOIN T_ACCOUNT a ON ve.ACCOUNT_CODE = a.ACCOUNT_CODE WHERE v.IS_DELETED = 0 AND ve.IS_DELETED = 0 AND v.BOOK_ID = #{bookId} AND v.TENANT_ID = #{tenantId}
AND v.VOUCHER_DATE >= #{startDate}
AND v.VOUCHER_DATE <= #{endDate}
AND ve.ACCOUNT_CODE IS NOT NULL GROUP BY ve.ACCOUNT_CODE, a.ACCOUNT_NAME ORDER BY usageCount DESC
FETCH NEXT #{limit} ROWS ONLY

SELECT
    SUM(TOTAL_DEBIT) as totalDebitAmount,
    SUM(TOTAL_CREDIT) as totalCreditAmount,
    AVG(TOTAL_DEBIT) as avgDebitAmount,
    AVG(TOTAL_CREDIT) as avgCreditAmount,
    MAX(TOTAL_DEBIT) as maxDebitAmount,
    MIN(TOTAL_DEBIT) as minDebitAmount
FROM T_ACCOUNTING_VOUCHER
WHERE IS_DELETED = 0 AND TENANT_ID = #{param.tenantId}

    AND BOOK_ID = #{param.bookId}


    AND VOUCHER_DATE >= #{param.startDate}


    AND VOUCHER_DATE <= #{param.endDate}

SELECT
    COUNT(*) as voucherCount,
    SUM(TOTAL_DEBIT) as totalAmount,
    VOUCHER_DATE as dateGroup
FROM T_ACCOUNTING_VOUCHER
WHERE IS_DELETED = 0 AND TENANT_ID = #{param.tenantId}

    AND BOOK_ID = #{param.bookId}


    AND VOUCHER_DATE >= #{param.startDate}


    AND VOUCHER_DATE <= #{param.endDate}

GROUP BY VOUCHER_DATE
ORDER BY dateGroup

SELECT s.SUBJECT_CODE as subjectCode, s.SUBJECT_NAME as subjectName, COUNT(e.ENTRY_ID) as usageCount, COALESCE(SUM(e.DEBIT_AMOUNT), 0) as totalDebit, COALESCE(SUM(e.CREDIT_AMOUNT), 0) as totalCredit FROM T_VOUCHER_ENTRY e INNER JOIN T_ACCOUNT_SUBJECT s ON e.SUBJECT_ID = s.SUBJECT_ID INNER JOIN T_ACCOUNTING_VOUCHER v ON e.VOUCHER_ID = v.VOUCHER_ID WHERE e.IS_DELETED = 0 AND e.TENANT_ID = #{param.tenantId}
AND e.BOOK_ID = #{param.bookId}
AND v.VOUCHER_DATE >= #{param.startDate}
AND v.VOUCHER_DATE <= #{param.endDate}
GROUP BY s.SUBJECT_CODE, s.SUBJECT_NAME ORDER BY usageCount DESC

SELECT
    COUNT(*) as totalVouchers,
    AVG(CASE WHEN AUDIT_TIME IS NOT NULL
        THEN 0 -- 暂时返回0，避免SQL语法错误
        ELSE NULL END) as avgReviewMinutes
FROM T_ACCOUNTING_VOUCHER
WHERE IS_DELETED = 0 AND TENANT_ID = #{param.tenantId}

    AND BOOK_ID = #{param.bookId}


    AND VOUCHER_DATE >= #{param.startDate}


    AND VOUCHER_DATE <= #{param.endDate}

-- 借贷不平衡的凭证 SELECT v.VOUCHER_ID as voucherId, v.VOUCHER_NO as voucherNo, '借贷不平衡' as anomalyType, ABS(v.TOTAL_DEBIT - v.TOTAL_CREDIT) as differenceAmount, v.VOUCHER_DATE as voucherDate FROM T_ACCOUNTING_VOUCHER v WHERE v.IS_DELETED = 0 AND v.TENANT_ID = #{param.tenantId}
AND v.BOOK_ID = #{param.bookId}
AND v.VOUCHER_DATE >= #{param.startDate}
AND v.VOUCHER_DATE <= #{param.endDate}
AND ABS(v.TOTAL_DEBIT - v.TOTAL_CREDIT) > 0.01
UNION ALL
-- 缺少分录的凭证 SELECT v.VOUCHER_ID as voucherId, v.VOUCHER_NO as voucherNo, '缺少分录' as anomalyType, COUNT(e.ENTRY_ID) as entryCount, v.VOUCHER_DATE as voucherDate FROM T_ACCOUNTING_VOUCHER v LEFT JOIN T_VOUCHER_ENTRY e ON v.VOUCHER_ID = e.VOUCHER_ID AND e.IS_DELETED = 0 WHERE v.IS_DELETED = 0 AND v.TENANT_ID = #{param.tenantId}
AND v.BOOK_ID = #{param.bookId}
AND v.VOUCHER_DATE >= #{param.startDate}
AND v.VOUCHER_DATE <= #{param.endDate}
GROUP BY v.VOUCHER_ID, v.VOUCHER_NO, v.VOUCHER_DATE HAVING COUNT(e.ENTRY_ID) < 2

SELECT
    COUNT(*) as reviewCount,
    SUM(CASE WHEN AUDIT_STATUS = 2 THEN 1 ELSE 0 END) as rejectedCount,
    CAST(SUM(CASE WHEN AUDIT_STATUS = 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS DECIMAL(10,2)) as rejectionRate
FROM T_ACCOUNTING_VOUCHER
WHERE IS_DELETED = 0 AND TENANT_ID = #{param.tenantId}

    AND BOOK_ID = #{param.bookId}


    AND VOUCHER_DATE >= #{param.startDate}


    AND VOUCHER_DATE <= #{param.endDate}
